var n=`0625-libyan-couscous`;var a=`world-0625`;var i=`LY`;var s=`northern-africa`;var o=4;var r=81;var l={en:`Libyan Couscous`,ua:`Лівійський кускус`};var g={en:`Libyan Couscous is a Libya classic prepared with lamb, yellow onion, tomato, tomato paste. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Лівійський кускус, страва кухні країни Лівія зі складниками: ягнятина, жовта цибуля, помідор, томатна паста. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`lamb`,600,`g`],[`yellow-onion`,170,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`tomato`,360,`g`],[`tomato-paste`,40,`g`],[`water`,970,`ml`],[`potato`,300,`g`],[`carrot`,230,`g`],[`canned-chickpeas`,190,`g`]]},{en:`Steam the moistened grains or processed granules in a covered basket for about 16 minutes; fluff, separate and check tenderness before serving.`,ua:`Пропарте зволожену крупу або готові гранули в закритому кошику приблизно 16 хвилин; розпушіть, розділіть і перевірте м’якість перед подаванням.`,t:[`couscous-steaming`],m:16,i:[[`couscous`,360,`g`],[`water`,400,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:5,i:[[`ras-el-hanout`,6,`g`],[`table-salt`,null,`to_taste`]]}];var m={slug:n,id:a,country:`LY`,region:s,servings:4,minutes:81,title:l,text:g,steps:u};export{i as country,m as default,a as id,r as minutes,s as region,o as servings,n as slug,u as steps,g as text,l as title};